package com.techstore.order;
import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import org.springframework.web.client.RestClientResponseException; import java.util.List;
@RestController @RequestMapping("/api/orders") public class OrderController {private final OrderRepository orders;private final ProductClient products;public OrderController(OrderRepository o,ProductClient p){orders=o;products=p;}
 @GetMapping public List<CustomerOrder> all(){return orders.findAll();}
 @GetMapping("/{id}") public CustomerOrder get(@PathVariable Long id){return orders.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Orden no encontrada"));}
 @PostMapping @ResponseStatus(HttpStatus.CREATED) public CustomerOrder create(@Valid @RequestBody OrderRequest r){if(r.quantity()<1)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"quantity debe ser mayor que cero");try{ProductClient.ProductDto p=products.decreaseStock(r.productId(),r.quantity());return orders.save(new CustomerOrder(p.id(),r.quantity(),p.price()));}catch(RestClientResponseException e){HttpStatus status=e.getStatusCode().value()==404?HttpStatus.NOT_FOUND:e.getStatusCode().value()==409?HttpStatus.CONFLICT:HttpStatus.BAD_GATEWAY;throw new ResponseStatusException(status,"No se pudo reservar stock: "+e.getResponseBodyAsString(),e);}catch(Exception e){if(e instanceof ResponseStatusException rse)throw rse;throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"No fue posible completar la orden con product-service",e);}}
}